<?php
namespace App\Http\Controllers;
use App\Models\{ServiceOrder,AuditLog};use Illuminate\Http\Request;
class OsController extends Controller{public const STAGES=['Entrada','Desmontagem','Bobinagem','Montagem','Testes','Finalização'];public function index(Request $request){$q=$request->string('q')->trim()->toString();$orders=ServiceOrder::query()->when($q,fn($x)=>$x->where(fn($w)=>$w->where('number','like',"%$q%")->orWhere('client_name','like',"%$q%")))->latest()->paginate(20)->withQueryString();return view('os.index',compact('orders','q'));}public function store(Request $request){abort_unless($request->user()?->canCreateOs(),403);$data=$request->validate(['number'=>'required|string|max:50|unique:service_orders,number','client_name'=>'required|string|max:255']);$order=ServiceOrder::create($data);AuditLog::create(['user_id'=>$request->user()->id,'action'=>'os.created','service_order_id'=>$order->id]);return redirect()->route('os.show',$order)->with('ok','OS criada.');}public function show(ServiceOrder $os){$stages=self::STAGES;$photos=$os->photos()->latest('captured_at')->get()->groupBy('stage');return view('os.show',compact('os','stages','photos'));}public function status(Request $request,ServiceOrder $os){abort_unless($request->user()?->canCreateOs(),403);$data=$request->validate(['status'=>'required|in:aberta,em_andamento,aguardando,finalizada,cancelada']);$old=$os->status;$os->update(['status'=>$data['status']]);AuditLog::create(['user_id'=>$request->user()->id,'action'=>'os.status_changed','service_order_id'=>$os->id,'metadata'=>['from'=>$old,'to'=>$os->status]]);return back()->with('ok','Status atualizado.');}}
